mapper.select:
SELECT * FROM ( SELECT ROWNUM AS rn, t.* FROM ( SELECT WELFARE_ID AS welfareId, LCLSF_NM AS lclsfNm, JSON_VALUE(FULL_DATA, '$.plcyNm') AS plcyNm, JSON_VALUE(FULL_DATA, '$.aplyYmd') AS aplyYmd, JSON_VALUE(FULL_DATA, '$.sprvsnInstCdNm') AS sprvsnInstCdNm FROM WELFARE WHERE 1=1
AND JSON_VALUE(FULL_DATA, '$.plcyNm') LIKE '%' || #{keyword} || '%'
AND LCLSF_NM = #{lclsfNm}
ORDER BY WELFARE_ID DESC ) t WHERE ROWNUM <= #{page} + 14 ) WHERE rn > #{page}

SELECT COUNT(*) FROM WELFARE WHERE 1=1
AND JSON_VALUE(FULL_DATA, '$.plcyNm') LIKE '%' || #{keyword} || '%'
AND LCLSF_NM = #{lclsfNm}
